      "services_saw_f1": "Lange Längsnähte: Träger, Kastenprofile, Bleche, Behältermäntel",
      "services_saw_f2": "Ausleger: Baumaschinen, Krane, Hubarbeitsbühnen",
      "services_saw_f3": "Rahmen: Anhänger, Auflieger, Land- und Baumaschinen",
      "services_saw_f4": "EN ISO 3834-2, Parameterdokumentation und ZfP",
      "services_saw_btn": "UP-Schweißen im Detail",
      "home_saw_eyebrow": "Neue Anlage",
      "home_saw_h2": "Unsere 35-m-UP-Schweißanlage <span style=\"color:var(--arc-2)\">ist in Betrieb.</span>",
      "home_saw_p": "UP-Schweißen für lange Längsnähte, Ausleger und Rahmen, in einer Aufspannung und reproduzierbarer Qualität.",
